/// One reported semantic change and every location where it occurs.
#[derive(Clone, Debug)]
pub struct ActualChange {
    pub kind: ChangeKind,
    pub occurrences: Vec<ActualChangeOccurrence>,
    /// Number of exact hunks emitted by the source [`ChangeEvent`].
    ///
    /// Event matching may coalesce exact hunks from one proved relation
    /// into one logical occurrence, but quality metrics must still report the public output's
    /// actual fragmentation.
    pub reported_hunk_count: usize,
}

#[derive(Clone, Debug)]
pub struct ActualChangeOccurrence {
    pub old_text: Option<String>,
    pub new_text: Option<String>,
    pub old_relation_context: Option<String>,
    pub new_relation_context: Option<String>,
    pub old_relation_context_len: Option<usize>,
    pub new_relation_context_len: Option<usize>,
    pub old_comparable_len: Option<usize>,
    pub new_comparable_len: Option<usize>,
    pub old_atomic_changed_tokens: Option<usize>,
    pub new_atomic_changed_tokens: Option<usize>,
    pub old_semantic_changed_tokens: Option<usize>,
    pub new_semantic_changed_tokens: Option<usize>,
    pub semantic_hunks: Option<Vec<ActualSemanticHunk>>,
    relation_trace: ActualRelationTraceStatus,
    pub resolvable: bool,
}

#[derive(Clone, Debug)]
enum ActualRelationTraceStatus {
    Available(ActualRelationTrace),
    Assessed { relation: usize },
    Ambiguous,
    Untraced,
}

#[derive(Clone, Debug)]
struct ActualRelationTrace {
    origin: ChangeOrigin,
    old_alignment_span_index: usize,
    new_alignment_span_index: usize,
    old_best_score: Option<u16>,
    old_second_score: Option<u16>,
    old_best_scope: Option<RecoveryWatchNearScopeReport>,
    new_best_score: Option<u16>,
    new_second_score: Option<u16>,
    new_best_scope: Option<RecoveryWatchNearScopeReport>,
}

#[derive(Clone, Debug)]
pub struct ActualSemanticHunk {
    pub old_text: Option<String>,
    pub new_text: Option<String>,
    pub old_atomic_changed_tokens: usize,
    pub new_atomic_changed_tokens: usize,
    pub old_range: Option<std::ops::Range<usize>>,
    pub new_range: Option<std::ops::Range<usize>>,
    atomic_fragments: Option<Vec<ActualAtomicFragment>>,
}

#[derive(Clone, Debug)]
struct ActualAtomicFragment {
    old_text: String,
    new_text: String,
    old_changed_tokens: usize,
    new_changed_tokens: usize,
}

#[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize)]
pub struct QualityMetrics {
    pub annotation: Annotation,
    pub expected_changes: usize,
    pub reported_changes: usize,
    pub recall: Option<f64>,
    pub precision: Option<f64>,
    pub kind_accuracy: Option<f64>,
    /// Reported hunks divided by quote-matched expected changes. Under
    /// `Partial` annotations the denominator is only the reviewed subset,
    /// so this overstates fragmentation and is not comparable with the
    /// complete-annotation `review_hunks_per_expected_change`.
    pub reported_hunks_per_matched_change: Option<f64>,
    /// Reported hunks per expected semantic change; computed only for
    /// `Complete` annotations where every semantic change was reviewed.
    pub review_hunks_per_expected_change: Option<f64>,
    pub unmatched_tiny_changes: usize,
    /// Occurrences with at least one existing side that could not be resolved.
    pub unresolvable_reported_spans: usize,
}

