fn missing_recovery_watch_side(quote: Option<&str>) -> RecoveryWatchOccurrenceReport {
    if quote.is_some() {
        RecoveryWatchOccurrenceReport::Unavailable
    } else {
        RecoveryWatchOccurrenceReport::NotQueried
    }
}

