    #[test]
    fn matched_relation_contexts_support_event_shapes_and_fail_closed_on_duplicates() {
        let old_blocks = [relation_block(1, "old relation context")];
        let new_blocks = [relation_block(2, "new relation context")];
        let old_map = build_block_map(&old_blocks);
        let new_map = build_block_map(&new_blocks);
        let trace = MatchedAtomicDiff {
            alignment_span_index: 0,
            old_context: relation_span(vec![BlockId(1)], None, 20),
            new_context: relation_span(vec![BlockId(2)], None, 20),
            edits: Vec::new(),
        };
        let contexts =
            matched_relation_contexts(std::slice::from_ref(&trace), [&old_map, &new_map]);

        for key in [
            relation_group_key(Some(&trace.old_context), Some(&trace.new_context)),
            relation_group_key(Some(&trace.old_context), None),
            relation_group_key(None, Some(&trace.new_context)),
        ] {
            let context = contexts
                .get(&key)
                .and_then(Option::as_ref)
                .expect("each event shape resolves one trace");
            assert_eq!(context.context.old, "old relation context");
            assert_eq!(context.context.new, "new relation context");
            assert_eq!(context.trace.origin, ChangeOrigin::OrderedAlignment);
            assert_eq!(context.trace.old_alignment_span_index, 0);
            assert_eq!(context.trace.new_alignment_span_index, 0);
        }

        let duplicates = matched_relation_contexts(&[trace.clone(), trace], [&old_map, &new_map]);
        assert!(duplicates.values().all(Option::is_none));
    }

    #[test]
    fn actual_occurrence_trace_distinguishes_available_ambiguous_and_untraced() {
        let old_blocks = [relation_block(1, "a "), relation_block(3, " bc")];
        let new_blocks = [relation_block(2, "a "), relation_block(4, " xc")];
        let old_map = build_block_map(&old_blocks);
        let new_map = build_block_map(&new_blocks);
        let old_context =
            relation_span(vec![BlockId(1), BlockId(3)], Some(BlockSeparator::Space), 5);
        let new_context =
            relation_span(vec![BlockId(2), BlockId(4)], Some(BlockSeparator::Space), 5);
        let mut old_changed = old_context.clone();
        old_changed.canonical_range = ScalarRange { start: 3, end: 4 };
        old_changed.comparable_range = TokenRange { start: 3, end: 4 };
        let mut new_changed = new_context.clone();
        new_changed.canonical_range = ScalarRange { start: 3, end: 4 };
        new_changed.comparable_range = TokenRange { start: 3, end: 4 };
        let trace = MatchedAtomicDiff {
            alignment_span_index: 7,
            old_context: old_context.clone(),
            new_context: new_context.clone(),
            edits: vec![pdfdelta_core::diff::AtomicEdit {
                old: 3..4,
                new: 3..4,
            }],
        };
        let occurrence = ChangeOccurrence {
            old_span: Some(old_changed),
            new_span: Some(new_changed),
        };
        let comparison = Comparison {
            changes: vec![pdfdelta_core::diff::ChangeEvent::single_occurrence(
                ChangeKind::Replacement,
                occurrence.old_span.clone(),
                occurrence.new_span.clone(),
                pdfdelta_core::diff::Confidence::High,
                Vec::new(),
            )],
            change_candidates: Vec::new(),
            assessment: None,
            proven_changed_regions: Vec::new(),
            formatting_changes: Vec::new(),
            unresolved_regions: Vec::new(),
            old_coverage: pdfdelta_core::diff::Coverage {
                resolved_tokens: 3,
                total_tokens: 3,
                ratio: Some(1.0),
            },
            new_coverage: pdfdelta_core::diff::Coverage {
                resolved_tokens: 3,
                total_tokens: 3,
                ratio: Some(1.0),
            },
        };

        let available = flatten_actual_changes(
            &comparison,
            [&old_map, &new_map],
            std::slice::from_ref(&trace),
            &[],
        );
        assert!(matches!(
            available[0].occurrences[0].relation_trace,
            ActualRelationTraceStatus::Available(ActualRelationTrace {
                origin: ChangeOrigin::OrderedAlignment,
                old_alignment_span_index: 7,
                new_alignment_span_index: 7,
                ..
            })
        ));
        assert_eq!(
            available[0].occurrences[0]
                .semantic_hunks
                .as_ref()
                .map(|hunks| &hunks[0].old_range),
            Some(&Some(2..3))
        );
        assert_eq!(
            available[0].occurrences[0]
                .semantic_hunks
                .as_ref()
                .map(|hunks| &hunks[0].new_range),
            Some(&Some(2..3))
        );

        let ambiguous = flatten_actual_changes(
            &comparison,
            [&old_map, &new_map],
            &[trace.clone(), trace],
            &[],
        );
        assert!(matches!(
            ambiguous[0].occurrences[0].relation_trace,
            ActualRelationTraceStatus::Ambiguous
        ));

        let untraced = flatten_actual_changes(&comparison, [&old_map, &new_map], &[], &[]);
        assert!(matches!(
            untraced[0].occurrences[0].relation_trace,
            ActualRelationTraceStatus::Untraced
        ));
    }

