    fn glyph_document(text: &str) -> Document<Glyph> {
        let glyphs = text
            .chars()
            .enumerate()
            .filter(|(_, character)| *character != ' ')
            .map(|(index, character)| Glyph {
                id: GlyphId(index as u64 + 1),
                text: DecodedText::Mapped(character.to_string()),
                raw_code: character.to_string().into_bytes(),
                page: PageId(0),
                bbox: Rect {
                    min: Vec2 {
                        x: index as f64 * 6.0,
                        y: 100.0,
                    },
                    max: Vec2 {
                        x: index as f64 * 6.0 + 5.0,
                        y: 110.0,
                    },
                },
                baseline: Vec2 {
                    x: index as f64 * 6.0,
                    y: 100.0,
                },
                direction: Vec2 { x: 1.0, y: 0.0 },
                font_id: FontId(1),
                font_size: 10.0,
                render_order: u32::try_from(index).expect("fixture glyph index fits in u32"),
                render_mode: TextRenderMode::Fill,
                crop_status: GlyphCropStatus::Inside,
                path_clip_status: GlyphPathClipStatus::Unclipped,
                provenance: GlyphProvenance {
                    content_stream: ObjectRef {
                        object_number: 1,
                        generation: 0,
                    },
                    operator_index: u32::try_from(index).expect("fixture glyph index fits in u32"),
                },
            })
            .collect();
        Document::new(glyphs)
    }

    #[test]
    fn assessed_disjoint_masks_match_one_logical_occurrence() {
        let document = |footer: &str| {
            let mut glyphs = Vec::new();
            for (text, x, y) in [
                ("Left body remains open", 0.0, 300.0),
                ("Right body remains open", 300.0, 300.0),
                ("Left remainder remains open", 0.0, 288.0),
                ("Right remainder remains open", 300.0, 288.0),
                (footer, 0.0, 30.0),
            ] {
                for mut glyph in glyph_document(text).items().iter().cloned() {
                    glyph.id = GlyphId(glyphs.len() as u64 + 1);
                    glyph.render_order = glyphs.len() as u32;
                    glyph.bbox.min.x += x;
                    glyph.bbox.max.x += x;
                    glyph.bbox.min.y += y - 100.0;
                    glyph.bbox.max.y += y - 100.0;
                    glyph.baseline.x += x;
                    glyph.baseline.y = y;
                    glyphs.push(glyph);
                }
            }
            Document::new(glyphs)
        };
        for (old_quote, new_quote, old_ranges, new_ranges, changed) in [
            (". F", "; f", vec![0..1, 2..3], vec![0..1, 2..3], 4),
            (
                "Cat. No. 11320B Form 1040 (2024)",
                "Cat. No. 11320B Form 1040 (2025) Created 9/5/25",
                std::iter::once(30..31).collect(),
                vec![30..31, 32..47],
                17,
            ),
        ] {
            let make = |quote: &str| {
                if quote.starts_with("Cat.") {
                    document(&format!(
                        "Reviewed catalog instructions remain available. {quote}"
                    ))
                } else {
                    glyph_document(quote)
                }
            };
            let ComparisonWithMetrics {
                outcome,
                matched_atomic_diffs,
                recovered_atomic_diffs,
                ..
            } = compare_outcomes_with_metrics(
                ExtractionOutcome::complete(make(old_quote)),
                ExtractionOutcome::complete(make(new_quote)),
                PipelineOptions::default(),
                &[],
            )
            .expect("source comparison");
            assert_eq!(outcome.comparison.changes.len(), 1);
            assert_eq!(outcome.comparison.changes[0].occurrences.len(), 2);
            let maps = [
                build_block_map(&outcome.old_blocks),
                build_block_map(&outcome.new_blocks),
            ];
            let actuals = flatten_actual_changes(
                &outcome.comparison,
                [&maps[0], &maps[1]],
                &matched_atomic_diffs,
                &recovered_atomic_diffs,
            );
            assert_eq!(actuals[0].occurrences.len(), 1, "{actuals:#?}");
            assert_eq!(actuals[0].reported_hunk_count, 2);
            let occurrence = &actuals[0].occurrences[0];
            assert_eq!(
                occurrence
                    .old_atomic_changed_tokens
                    .expect("old exact count")
                    + occurrence
                        .new_atomic_changed_tokens
                        .expect("new exact count"),
                changed
            );
            let ranges = |ranges: Vec<std::ops::Range<usize>>| {
                ranges
                    .into_iter()
                    .map(|r| serde_json::json!({"start": r.start, "end": r.end}))
                    .collect::<Vec<_>>()
            };
            let expected: Vec<ExpectedChange> = serde_json::from_value(serde_json::json!([{
                "id":"disjoint", "kind":"replacement", "occurrence_count":1,
                "old_quote":old_quote, "new_quote":new_quote,
                "old_changed_ranges":ranges(old_ranges), "new_changed_ranges":ranges(new_ranges),
            }]))
            .expect("independent source annotation");
            assert_eq!(
                compute_quality(Annotation::Partial, &expected, &actuals).recall,
                Some(1.0)
            );
            let mut reversed = outcome.comparison.clone();
            reversed.changes[0].occurrences.reverse();
            assert!(
                assessment_evidence::for_change(
                    &reversed,
                    0,
                    [&maps[0], &maps[1]],
                    &mut MatchingScanBudget::default()
                )
                .is_none()
            );
        }
    }

    #[test]
    fn compare_outcomes_with_metrics_records_candidate_visits_on_success() {
        let old =
            ExtractionOutcome::complete(glyph_document("Stable old paragraph remains visible"));
        let new =
            ExtractionOutcome::complete(glyph_document("Stable new paragraph remains visible"));

        let ComparisonWithMetrics {
            outcome,
            alignment,
            alignment_incomplete: _,
            metrics,
            sentence_recovery_metrics,
            pressure,
            recovery_watch_diagnostics: _,
            matched_atomic_diffs: _,
            recovered_atomic_diffs: _,
        } = compare_outcomes_with_metrics(old, new, PipelineOptions::default(), &[])
            .expect("comparison succeeds");

        assert!(!outcome.comparison.changes.is_empty());
        assert!(alignment.is_some());
        let sentence_recovery_metrics = sentence_recovery_metrics
            .expect("completed exact diff records sentence recovery metrics");
        assert!(sentence_recovery_metrics.old_trusted_run_source_tokens > 0);
        assert!(sentence_recovery_metrics.new_trusted_run_source_tokens > 0);
        let visits = metrics.candidate_visits.expect("candidate visits recorded");
        assert!(visits > 0, "non-anchor old blocks must be charged");
        assert_eq!(
            metrics.candidate_visits_required,
            Some(visits),
            "attempted charge must equal the required sum on success"
        );
        let (exact, ngram, short_fallback) = (
            metrics
                .candidate_visits_required_exact
                .expect("inverted index reports a breakdown"),
            metrics
                .candidate_visits_required_ngram
                .expect("inverted index reports a breakdown"),
            metrics
                .candidate_visits_required_short_fallback
                .expect("inverted index reports a breakdown"),
        );
        assert_eq!(
            exact + ngram + short_fallback,
            visits,
            "required components must sum to the required total"
        );
        assert_eq!(
            metrics.max_candidate_visits,
            Some(AlignmentOptions::default().max_candidate_visits)
        );
        let pressure = pressure.expect("pressure recorded for complete extraction");
        assert_eq!(
            pressure.max_candidate_visits,
            AlignmentOptions::default().max_candidate_visits
        );
    }

