    #[test]
    fn converts_serializes_and_validates_sentence_edge_signature_reference_oracle() {
        let oracle = valid_sentence_edge_signature_reference_oracle();
        let report = validate_sentence_recovery_metrics(SentenceRecoveryMetrics {
            sentence_edge_signature_reference_oracle: Some(oracle),
            sentence_edge_filter_complete: true,
            ..SentenceRecoveryMetrics::default()
        })
        .expect("valid reference oracle passes")
        .sentence_edge_signature_reference_oracle
        .expect("reference oracle report exists");
        assert_eq!(report, oracle.into());
        let serialized = serde_json::to_value(report).expect("reference oracle serializes");
        assert_eq!(serialized["legacy_sentence_edge_pairs_examined"], 7);
        assert_eq!(serialized["legacy_sentence_edge_pairs_attempted"], 7);
        assert_eq!(serialized["legacy_sentence_edge_pairs_retained"], 2);
        assert_eq!(serialized["legacy_sentence_edge_pairs_rejected"], 5);
        let keys = serialized
            .as_object()
            .expect("reference oracle is an object")
            .keys()
            .cloned()
            .collect::<HashSet<_>>();
        assert_eq!(
            keys,
            HashSet::from([
                "complete",
                "stop_reason",
                "direct_complete",
                "legacy_sentence_edge_pairs_examined",
                "legacy_sentence_edge_pairs_attempted",
                "legacy_sentence_edge_pairs_retained",
                "legacy_sentence_edge_pairs_rejected",
                "candidate_posting_visits_examined",
                "candidate_posting_visits_attempted",
                "edge_filter_pairs_examined",
                "edge_filter_pairs_attempted",
                "edge_filter_similarity_comparisons_examined",
                "edge_filter_similarity_comparisons_attempted",
                "pair_visits_examined",
                "pair_visits_attempted",
                "similarity_comparisons_examined",
                "similarity_comparisons_attempted",
                "fragment_veto_pair_visits_examined",
                "fragment_veto_pair_visits_attempted",
                "fragment_veto_similarity_comparisons_examined",
                "fragment_veto_similarity_comparisons_attempted",
                "candidate_count_truncated",
                "plan_parity_evaluable",
                "plan_parity",
                "fingerprint_evaluable",
                "retained_pair_misses",
                "retained_pair_count_mismatches",
                "retained_pair_set_mismatches",
                "retained_pair_order_mismatches",
            ])
            .into_iter()
            .map(str::to_owned)
            .collect()
        );

        let mismatch = SentenceEdgeSignatureReferenceOracleMetrics {
            plan_parity: false,
            retained_pair_set_mismatches: 1,
            retained_pair_order_mismatches: 1,
            ..oracle
        };
        assert!(
            validate_sentence_recovery_metrics(SentenceRecoveryMetrics {
                sentence_edge_signature_reference_oracle: Some(mismatch),
                sentence_edge_filter_complete: true,
                ..SentenceRecoveryMetrics::default()
            })
            .is_ok()
        );
        for invalid in [
            SentenceEdgeSignatureReferenceOracleMetrics {
                complete: false,
                ..oracle
            },
            SentenceEdgeSignatureReferenceOracleMetrics {
                direct_complete: false,
                ..oracle
            },
            SentenceEdgeSignatureReferenceOracleMetrics {
                pair_visits_attempted: 5,
                ..oracle
            },
            SentenceEdgeSignatureReferenceOracleMetrics {
                legacy_sentence_edge_pairs_attempted: 8,
                ..oracle
            },
            SentenceEdgeSignatureReferenceOracleMetrics {
                legacy_sentence_edge_pairs_retained: 3,
                ..oracle
            },
            SentenceEdgeSignatureReferenceOracleMetrics {
                fingerprint_evaluable: false,
                retained_pair_set_mismatches: 1,
                ..oracle
            },
        ] {
            assert!(
                validate_sentence_recovery_metrics(SentenceRecoveryMetrics {
                    sentence_edge_signature_reference_oracle: Some(invalid),
                    sentence_edge_filter_complete: true,
                    ..SentenceRecoveryMetrics::default()
                })
                .is_err()
            );
        }
    }

    #[test]
    fn validates_reference_oracle_typed_stops_and_partial_evidence() {
        use SentenceEdgeSignatureReferenceOracleStopReason as Stop;
        let validates = |oracle| {
            validate_sentence_recovery_metrics(SentenceRecoveryMetrics {
                sentence_edge_signature_reference_oracle: Some(oracle),
                sentence_edge_filter_complete: true,
                ..SentenceRecoveryMetrics::default()
            })
        };
        macro_rules! resource_stop_case {
            ($reason:ident, $examined:ident, $attempted:ident) => {{
                let mut stopped = valid_sentence_edge_signature_reference_oracle();
                stopped.complete = false;
                stopped.stop_reason = Some(Stop::$reason);
                stopped.plan_parity_evaluable = false;
                stopped.plan_parity = false;
                stopped.fingerprint_evaluable = false;
                stopped.$attempted = stopped.$examined + 1;
                assert!(validates(stopped).is_ok(), stringify!($reason));
                stopped.$attempted = stopped.$examined;
                assert!(validates(stopped).is_err(), stringify!($reason));
            }};
        }
        resource_stop_case!(
            CandidatePostingVisitLimit,
            candidate_posting_visits_examined,
            candidate_posting_visits_attempted
        );
        resource_stop_case!(PairVisitLimit, pair_visits_examined, pair_visits_attempted);
        resource_stop_case!(
            EdgeFilterPairVisitLimit,
            edge_filter_pairs_examined,
            edge_filter_pairs_attempted
        );
        resource_stop_case!(
            EdgeFilterSimilarityComparisonLimit,
            edge_filter_similarity_comparisons_examined,
            edge_filter_similarity_comparisons_attempted
        );
        resource_stop_case!(
            SimilarityComparisonLimit,
            similarity_comparisons_examined,
            similarity_comparisons_attempted
        );
        resource_stop_case!(
            FragmentVetoPairVisitLimit,
            fragment_veto_pair_visits_examined,
            fragment_veto_pair_visits_attempted
        );
        resource_stop_case!(
            FragmentVetoSimilarityComparisonLimit,
            fragment_veto_similarity_comparisons_examined,
            fragment_veto_similarity_comparisons_attempted
        );
        let mut mixed_edge_filter_stop = valid_sentence_edge_signature_reference_oracle();
        mixed_edge_filter_stop.complete = false;
        mixed_edge_filter_stop.stop_reason = Some(Stop::EdgeFilterPairVisitLimit);
        mixed_edge_filter_stop.plan_parity_evaluable = false;
        mixed_edge_filter_stop.plan_parity = false;
        mixed_edge_filter_stop.fingerprint_evaluable = false;
        mixed_edge_filter_stop.edge_filter_pairs_attempted += 1;
        mixed_edge_filter_stop.pair_visits_attempted += 1;
        assert!(validates(mixed_edge_filter_stop).is_err());

        let mut partial_edge_comparison = valid_sentence_edge_signature_reference_oracle();
        partial_edge_comparison.complete = false;
        partial_edge_comparison.stop_reason = Some(Stop::EdgeFilterSimilarityComparisonLimit);
        partial_edge_comparison.plan_parity_evaluable = false;
        partial_edge_comparison.plan_parity = false;
        partial_edge_comparison.fingerprint_evaluable = false;
        partial_edge_comparison.legacy_sentence_edge_pairs_attempted += 1;
        partial_edge_comparison.edge_filter_pairs_examined += 1;
        partial_edge_comparison.edge_filter_pairs_attempted += 1;
        partial_edge_comparison.edge_filter_similarity_comparisons_attempted += 1;
        assert!(validates(partial_edge_comparison).is_ok());

        let direct_incomplete = SentenceEdgeSignatureReferenceOracleMetrics {
            stop_reason: Some(Stop::DirectReplayIncomplete),
            ..SentenceEdgeSignatureReferenceOracleMetrics::default()
        };
        assert!(validates(direct_incomplete).is_ok());
        let authoritative_partial = SentenceEdgeSignatureReferenceOracleMetrics {
            plan_parity_evaluable: true,
            plan_parity: true,
            ..direct_incomplete
        };
        assert!(validates(authoritative_partial).is_err());

        let partial_legacy_edge_work = SentenceEdgeSignatureReferenceOracleMetrics {
            complete: false,
            stop_reason: Some(Stop::PairVisitLimit),
            direct_complete: true,
            legacy_sentence_edge_pairs_examined: 4,
            legacy_sentence_edge_pairs_attempted: 5,
            legacy_sentence_edge_pairs_retained: 1,
            legacy_sentence_edge_pairs_rejected: 3,
            pair_visits_examined: 2,
            pair_visits_attempted: 3,
            ..SentenceEdgeSignatureReferenceOracleMetrics::default()
        };
        assert!(validates(partial_legacy_edge_work).is_ok());
        assert!(
            validates(SentenceEdgeSignatureReferenceOracleMetrics {
                legacy_sentence_edge_pairs_examined: 3,
                ..partial_legacy_edge_work
            })
            .is_err()
        );
        assert!(
            validates(SentenceEdgeSignatureReferenceOracleMetrics {
                legacy_sentence_edge_pairs_rejected: 2,
                ..partial_legacy_edge_work
            })
            .is_err()
        );
        assert!(
            validates(SentenceEdgeSignatureReferenceOracleMetrics {
                stop_reason: Some(Stop::CounterOverflow),
                legacy_sentence_edge_pairs_examined: usize::MAX,
                legacy_sentence_edge_pairs_attempted: usize::MAX,
                legacy_sentence_edge_pairs_retained: usize::MAX,
                legacy_sentence_edge_pairs_rejected: 1,
                pair_visits_examined: 2,
                pair_visits_attempted: 2,
                ..partial_legacy_edge_work
            })
            .is_err()
        );

        let counter_overflow = SentenceEdgeSignatureReferenceOracleMetrics {
            complete: false,
            stop_reason: Some(Stop::CounterOverflow),
            direct_complete: true,
            legacy_sentence_edge_pairs_examined: 4,
            legacy_sentence_edge_pairs_attempted: 5,
            legacy_sentence_edge_pairs_retained: 1,
            legacy_sentence_edge_pairs_rejected: 3,
            ..SentenceEdgeSignatureReferenceOracleMetrics::default()
        };
        assert!(validates(counter_overflow).is_ok());
        assert!(
            validates(SentenceEdgeSignatureReferenceOracleMetrics {
                legacy_sentence_edge_pairs_rejected: 2,
                ..counter_overflow
            })
            .is_err()
        );
    }

